#!/usr/bin/env python3
"""Create only the authorized new text bundle; require all final-byte receipts."""
import hashlib,json,pathlib,re,subprocess,tarfile
P=pathlib.Path('/tmp/cadence-ch05-wakeup-evidence');N=pathlib.Path('/Users/bill/projects/ensemble/docs/edition-3-notes');D=N/'ch05-wakeup-student-evidence';R=N/'ch05-wakeup-student.md';S=N/'ch05-wakeup-student-source-manifest.json';I=N/'ch05-wakeup-student-evidence-manifest.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
identity=json.loads((P/'candidate-r2/frozen/identity.json').read_text());root=pathlib.Path(identity['source_root'])
assert not subprocess.check_output(['git','status','--porcelain'],cwd=root)
assert subprocess.check_output(['git','rev-parse','HEAD'],cwd=root,text=True).strip()==identity['source_commit']
for name,digest in identity['source_files'].items():assert sha(root/name)==sha(P/'source-snapshot'/name)==digest,name
assert sha(pathlib.Path(identity['source_archive']['path']))==identity['source_archive']['sha256']
with tarfile.open(identity['source_archive']['path']) as tar:
 members={m.name:m for m in tar.getmembers() if m.isfile()};assert set(members)==set(identity['source_files'])
 for name,digest in identity['source_files'].items():assert hashlib.sha256(tar.extractfile(members[name]).read()).hexdigest()==digest
for item in identity['binaries'].values():assert sha(pathlib.Path(item['path']))==item['sha256']
gates=json.loads((P/'candidate-r2/gates/commands.json').read_text());assert len(gates)==13 and all(g['exit']==0 and g['source_commit']==identity['source_commit'] for g in gates)
controls=json.loads((P/'sensitivity-compatible/commands.json').read_text());assert len(controls)==8 and all(c['valid'] for c in controls) and all(c['exit']==1 for c in controls[:7]) and controls[-1]['exit']==0
local=json.loads((P/'local-wakeup-r5/summary.json').read_text());assert local['passed'] and local['source_commit']==identity['source_commit'] and local['binaries']==identity['binaries'] and local['paid_requests']==0
assert (P/'local-wakeup-r5.exit').read_text().strip()=='0'
grades=json.loads((P/'candidate-r2/frozen/grade-commands-and-exits.json').read_text());assert [g['chapter'] for g in grades]==[5,1]
for g in grades:
 assert g['exit']==0 and g['candidate_commit']==identity['source_commit'] and g['cli_sha256']==identity['binaries']['cli']['sha256']
 result=json.loads((P/f"candidate-r2/frozen/grade-ch{g['chapter']:02}.json").read_text());assert result['passed'] and result['score']==100
assert (P/'candidate-r2/public-grades.exit').read_text().strip()=='0'
assert json.loads((P/'prior-preservation.json').read_text())['passed']
(P/'final-state.json').write_text(json.dumps({'source_commit':identity['source_commit'],'tree':identity['source_tree'],'clean':True,'source_archive_files':len(identity['source_files']),'binaries':identity['binaries'],'local_gates':13,'public_grade_exits':[g['exit'] for g in grades],'paid_calls_this_amendment':0,'credential_reads':0,'children':0,'acceptance_tag_created':False,'main_commit_created':False},indent=2)+'\n')
files={};excluded={};omitted=[];suspected=[];pattern=re.compile(rb'(?:sk-ant-[A-Za-z0-9_-]{20,}|sk-proj-[A-Za-z0-9_-]{20,}|AIza[0-9A-Za-z_-]{30,})')
for path in sorted(P.rglob('*')):
 if not path.is_file():continue
 rel=str(path.relative_to(P));parts=path.relative_to(P).parts
 if len(parts)>1 and parts[0].startswith('sensitivity') and parts[1]=='source':
  name='/'.join(parts[:2])
  if name not in omitted:omitted.append(name)
  continue
 raw=path.read_bytes();meta={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw)}
 binary=path.suffix.lower() in ['.tar','.gz','.png','.pyc','.pdf','.jpg','.wav','.mp3','.mp4'] or b'\0' in raw
 if not binary:
  try:raw.decode('utf-8')
  except UnicodeError:binary=True
 if binary:
  excluded[rel]={**meta,'local_path':str(path),'reason':'binary/archive/generated bytecode remains outside Git'};continue
 if pattern.search(raw):suspected.append(rel)
 files[rel]=meta
assert not suspected,('possible secret-shaped data; stopped without displaying bytes',suspected)
if D.exists():
 existing={str(p.relative_to(D)) for p in D.rglob('*') if p.is_file()};assert existing<=set(files),'unexpected destination files'
 for rel in existing:assert sha(D/rel)==files[rel]['sha256'],rel
D.mkdir(exist_ok=True)
for rel,m in files.items():
 dest=D/rel;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_bytes((P/rel).read_bytes());assert sha(dest)==m['sha256']
source=(P/'candidate-r2/frozen/identity.json').read_bytes()
if S.exists():assert S.read_bytes()==source
S.write_bytes(source)
index={'schema':1,'portable_directory':D.name,'text_files':files,'excluded_artifacts':excluded,'omitted_duplicate_scratch_trees':omitted,'report':{'relative_path':R.name,'sha256':sha(R),'bytes':R.stat().st_size},'source_index':{'relative_path':S.name,'sha256':sha(S),'bytes':S.stat().st_size},'candidate':identity,'preservation_receipt':{'relative_path':'prior-preservation.json','sha256':files['prior-preservation.json']['sha256']},'evidence_credit':{'new_public_amendment':True,'formal_correction_rounds_used':1,'original_controls_compile_and_fail_behaviorally':7,'corrected_restored_exit':0,'ten_repeated_focused_race_exit':0,'all13_final_local_gate_exits':0,'actual_CLI_workflow_local_launcher_exit':0,'public_grades':grades,'historical_grader_does_not_cover_new_contract':True,'setup_failures_count_as_detections':False,'original12_paid_calls_remain_00489_only':True},'privacy':{'real_provider_calls_this_amendment':0,'credential_lookup':False,'possible_secret_shaped_matches':0,'HTTP_and_histories_are_synthetic_loopback_only':True,'no_real_provider_opaque_or_private_conversation_collected':True},'relocation':'verify-portable.py checks relative text/report/source index and48-file source snapshot; exact source archives and binaries remain outside Git'}
I.write_text(json.dumps(index,indent=2)+'\n')
print(json.dumps({'text_files':len(files),'excluded_local_artifacts':len(excluded),'candidate':identity['source_commit'],'report_sha256':sha(R),'source_index_sha256':sha(S),'evidence_index_sha256':sha(I)},indent=2))
